// 1. Берем результат от Gemini
const geminiResult = $json;
let geminiResponse = "";

if (geminiResult.content && geminiResult.content.parts && geminiResult.content.parts.length > 0) {
    geminiResponse = geminiResult.content.parts[0].text;
} else {
    geminiResponse = geminiResult.text || geminiResult.output || "БРАК | Текст не распознан";
}

// 2. Разбиваем ответ на Вердикт (OK/БРАК) и Транскрипцию по символу "|"
let verdict = "ОШИБКА АНАЛИЗА";
let llmTranscript = geminiResponse;

if (geminiResponse.includes('|')) {
    const parts = geminiResponse.split('|');
    verdict = parts[0].trim(); // Берем то, что до палочки (OK или БРАК)
    // Берем всё, что после палочки (на случай если в самом тексте тоже будет символ |)
    llmTranscript = parts.slice(1).join('|').trim(); 
} else {
    // Если Gemini забыл поставить разделитель
    verdict = "БЕЗ ВЕРДИКТА";
    llmTranscript = geminiResponse;
}

// 3. Берем данные текущего файла из ноды цикла
const currentFile = $('Loop: Process Each Audio / Цикл: Обробка файлів').item.json;

// 4. Берем весь датасет
const datasetRows = $('Parse CSV Data / Читання даних CSV').all();

const fileName = currentFile.name || "unknown";
const timecodeRegex = /\d{2}h\d{2}m\d{2}\.\d{3}---\d{2}h\d{2}m\d{2}\.\d{3}/;

// Ищем таймкод
const fileMatch = fileName.match(timecodeRegex);
const fileTimecode = fileMatch ? fileMatch[0] : null;

let originalTranscript = "Не найден в датасете";
let speaker = "Неизвестен";

if (fileTimecode) {
    const row = datasetRows.find(r => (r.json.file || "").includes(fileTimecode));
    if (row) {
        originalTranscript = row.json.transcript || row.json.corrected_transcript;
        speaker = row.json.speaker;
    }
}

// ВОЗВРАЩАЕМ ДАННЫЕ ВМЕСТЕ С НОВОЙ КОЛОНКОЙ "Вердикт"
return {
    "Имя файла": fileName,
    "Спикер": speaker,
    "Вердикт": verdict,
    "Оригинальный текст (Dataset)": originalTranscript,
    "Текст от LLM (Gemini)": llmTranscript
};
